<script lang="ts">import type {Snippet} from "svelte";import {createPopoverController} from "@weiui/core";import {normalizeSvelteProps} from "./internal.js";let {open=$bindable(false),trigger="Open",closeLabel="Close",id="wui-popover",children}=$props<{open?:boolean;trigger?:string;closeLabel?:string;id?:string;children?:Snippet}>();const controller=createPopoverController({id,defaultOpen:open,onOpenChange:next=>open=next});let state=$state(controller.getState());$effect(()=>{const off=controller.subscribe(next=>state=next);return off});$effect(()=>{if(open!==state.open)controller.syncOpen(open)});function p(kind:"root"|"trigger"|"content"|"close"){state;return normalizeSvelteProps(kind==="root"?controller.getRootProps():kind==="trigger"?controller.getTriggerProps():kind==="content"?controller.getContentProps():controller.getCloseProps())}</script><div {...p("root")} class="wui-popover"><button {...p("trigger")} class="wui-popover__trigger">{trigger}</button>{#if state.open}<div {...p("content")} class="wui-popover__content">{@render children?.()}<button {...p("close")} class="wui-popover__close">{closeLabel}</button></div>{/if}</div>
